"""Interpret completed Part M outputs only; no model calls or method changes."""
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT))
import numpy as np,pandas as pd
from src.week12.protocol import load,sha,digest,Store,immutable
from src.week12_confirmation.freeze_guard import verify,folder,protocol,FREEZE_SHA,SPLIT_SHA,METHODS,BUDGETS
from src.week12_confirmation.confirmation_analysis import completed_rows

def main():
 cfg=load();f,s=verify(cfg);p=folder();ident=protocol(cfg);rows=completed_rows(p,ident)
 expected={(d,q,m,b) for d,qs in f['confirmation_ids'].items() for q in qs for m in METHODS for b in BUDGETS}
 assert {(r['dataset'],r['query_id'],r['method'],r['budget']) for r in rows}==expected
 groups={(d,r['query_id']):r['group'] for d,x in s['datasets'].items() for r in x['CONFIRM']}
 for r in rows:
  assert r['cluster_id']==groups[r['dataset'],r['query_id']]
  assert r['evidence_tokens']<=r['budget'] and r['evidence_tokens']==len(r['evidence_token_ids'])
  assert r['evidence_hash']==digest([r['evidence_token_ids'],r['evidence_text']])
  assert r['reader_identity']==dict(cfg['models']['Qwen'],precision='BASE_FP16') and r['model_hash']==digest([cfg['models']['Qwen'],'BASE_FP16',None])
  assert r['prompt_parser_source_hash']==sha(ROOT/'src/week12/reader.py') and r['generation_config']==dict(cfg['generation'],seed=cfg['seed'])
  assert r['source_provenance_validated'] and r['final_freeze_hash']==FREEZE_SHA
 S=pd.read_csv(p/'summary.csv');C=pd.read_csv(p/'contrasts.csv');V=pd.read_csv(p/'validation_comparison.csv');assert len(C)==12 and (C.resamples==10000).all()
 import matplotlib
 matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 plt.rcParams.update({'figure.dpi':150,'axes.spines.top':False,'axes.spines.right':False})
 figs=p/'figures';figs.mkdir(exist_ok=True)
 fig,axs=plt.subplots(1,2,figsize=(11,4))
 for ax,d in zip(axs,['HotpotQA','SciFact']):
  for m in METHODS:
   a=S[(S.dataset==d)&(S.method==m)].sort_values('budget');ax.plot(a.budget,a.quality,'o-',label=m)
  ax.set(title=d,xlabel='Evidence-token budget',ylabel='Answer F1' if d=='HotpotQA' else 'Three-class macro-F1',xticks=BUDGETS);ax.legend(fontsize=7);ax.grid(alpha=.2)
 fig.suptitle('Untouched confirmation — descriptive point estimates');fig.tight_layout();fig.savefig(figs/'quality_by_budget.png');plt.close(fig)
 fig,axs=plt.subplots(1,2,figsize=(12,5))
 for ax,d in zip(axs,['HotpotQA','SciFact']):
  a=C[C.dataset==d].reset_index(drop=True);ys=np.arange(len(a))
  for i,r in a.iterrows():ax.errorbar(r.point,i,xerr=[[r.point-r.ci_low],[r.ci_high-r.point]],fmt='o',color='#246a9c' if r.family=='primary' else '#a44a1c',capsize=3)
  ax.axvline(0,color='gray',lw=1);ax.set_yticks(ys,[f"FS − {r.right} @{r.budget}" for r in a.itertuples()],fontsize=8);ax.set(title=d,xlabel='Paired difference; nominal 95% cluster-bootstrap CI');ax.invert_yaxis();ax.grid(axis='x',alpha=.2)
 fig.suptitle('Blue: primary (8-test family); brown: secondary (4-test family)');fig.tight_layout();fig.savefig(figs/'paired_contrasts.png');plt.close(fig)
 audit=dict(freeze_sha=FREEZE_SHA,split_sha=SPLIT_SHA,logical_rows=len(rows),exact_membership=True,group_membership=True,result_checksums_verified=True,source_evidence_hashes_verified=True,model_prompt_parser_generation_identity_verified=True,budgets_verified=True,confirmation_counts={d:len(qs) for d,qs in f['confirmation_ids'].items()},physical_distinct_cached_generations=len(Store(p/'generation',ident).rows()),no_new_generation_by_this_report=True,no_post_confirmation_method_changes=True,summary_sha=sha(p/'summary.csv'),contrasts_sha=sha(p/'contrasts.csv'),validation_comparison_sha=sha(p/'validation_comparison.csv'))
 immutable(p/'FINAL_CLOSEOUT_AUDIT.json',audit)
 compact=S.pivot(index=['dataset','budget'],columns='method',values='quality').reset_index();compact=compact[['dataset','budget']+METHODS]
 directions=[]
 for r in C.itertuples():
  v=V[(V.dataset==r.dataset)&(V.budget==r.budget)&(V.method=='FIXED_SENTENCE')].iloc[0]
  key='VAL_'+r.right+'_contrast';directions.append(dict(dataset=r.dataset,budget=r.budget,contrast='FIXED_SENTENCE − '+r.right,VAL_delta=v[key],confirmation_delta=r.point,direction_repeated=np.sign(v[key])==np.sign(r.point)))
 D=pd.DataFrame(directions);assert D.direction_repeated.all()
 intro=['## Interpreted closeout','','**Part M is complete: 2,500/2,500 logical rows, all five systems, both budgets, all 250 frozen queries, and 2,213 distinct cached generations.** Exact membership/groups, result checksums, evidence budgets/hashes, reader/prompt/parser/decoding identities and both Part-I freeze copies were verified. No rows were dropped or replaced. This reporting step made no new model calls and changed no scientific setting.','','### What confirmation establishes','','The high-level validation pattern generalizes, with important limits. FIXED_SENTENCE has substantial evidence benefit over NONE in all four dataset/budget cells, survives the preregistered eight-contrast Holm correction, and remains a credible frozen simple policy. It is **not** the best point-estimate system in every cell and is not universally superior to passages or QBGF.','','### Primary quality summary','',compact.to_markdown(index=False,floatfmt='.6f'),'','HotpotQA uses answer F1; SciFact uses three-class macro-F1. Do not average these task scores across datasets. H3 point estimates are contextual/descriptive; no new H3 significance family was introduced.','','![Confirmation quality by budget](figures/quality_by_budget.png)','','### Question 1: Does the frozen evidence-assisted policy generalize?','','Yes, on these two reserved cohorts. FIXED_SENTENCE − NONE is **+0.29742** [0.24242, 0.35242] and **+0.29294** [0.24214, 0.34523] on HotpotQA at 256/1024. SciFact gains are **+0.33281** [0.13864, 0.51421] and **+0.37544** [0.19077, 0.54549]. Holm-adjusted p-values are 0.00080 for each HotpotQA contrast and 0.01260 for each SciFact contrast. This supports evidence benefit in the sampled setting; it does not isolate retrieval from selection as independent mechanisms.','','### Question 2: Sentence evidence versus passage RAG','','At 256, SciFact strongly favors FIXED_SENTENCE: **+0.28762** macro-F1 [0.09709, 0.47206], primary-family Holm p=0.03560. HotpotQA favors sentences only by point estimate: **+0.01467** [−0.03567, 0.06500], inconclusive. At 1024, RAW_SKIP has higher point estimates in both datasets: sentence-minus-passage is **−0.02606** [−0.05689, 0.00490] on HotpotQA and **−0.02391** [−0.11539, 0.06152] on SciFact. Both intervals include zero: describe passage recovery/competitiveness, not proven superiority or equivalence.','','RAW_SKIP is budget-matched passage RAG, not unrestricted/full-context RAG. Three SciFact @256 RAW_SKIP examples have empty evidence because no whole candidate fits; all three remain scored. This is a property of this whole-passage allocation control, not an outcome-based exclusion. The study does not prove sentences universally beat all possible passage allocators.','','### Secondary question: Did rejecting universal QBGF promotion remain reasonable?','','Confirmation is mixed. QBGF is better on HotpotQA @1024: FIXED_SENTENCE − QBGF = **−0.03438** [−0.05971, −0.01004], secondary-family Holm p=0.03160. This is a real predefined secondary result and must be acknowledged. HotpotQA @256 is effectively unresolved (−0.00329, interval spans zero). SciFact favors FIXED_SENTENCE: +0.01438 at 256 (inconclusive) and **+0.10943** at 1024 [0.01951, 0.20442]. The latter nominal interval is positive but its Holm-adjusted p=0.12809 does not survive the four-test secondary family. Bootstrap intervals are nominal; adjusted p-values come from the registered cluster label-swap test, so they need not yield identical thresholds.','','Thus the evidence does not establish a robust **universal** QBGF advantage, while also contradicting any claim that the frozen sentence policy is universally best. QBGF is not retroactively promoted; FIXED_SENTENCE remains the historically frozen final policy.','','![Predefined paired contrasts](figures/paired_contrasts.png)','','### Validation pattern versus confirmation','','All **12 predefined contrast point-estimate directions** match validation. This is descriptive consistency, not 12 independent replications: NONE is shared across budget labels and contrasts share queries/systems. Cohorts differ, so absolute VAL-to-confirmation changes are not paired tests.','',D.to_markdown(index=False,floatfmt='.6f'),'','The direction pattern repeats more clearly than any claim of identical effect magnitude. For example, SciFact FIXED_SENTENCE @256 is 0.70006 on VAL and 0.70142 on confirmation, while HotpotQA QBGF @1024 rises from 0.43234 to 0.46724. Neither shift licenses new tuning or dataset-specific winner selection.','','### Class errors, tokens and practical limits','','SciFact has **zero invalid-format outputs** for every system/budget; quality differences here are not driven by format violations. For FIXED_SENTENCE, NOT_ENOUGH_INFO recall remains limited (0.50 at 256; 0.4375 at 1024), despite high SUPPORT recall (0.95 at both). The class table below reports all precision/recall/F1 values; only 20 SUPPORT, 14 REFUTE and 16 NEI claims are available.','','FIXED_SENTENCE nearly fills each budget: mean evidence tokens are 254.76/1010.62 on HotpotQA and 254.30/1020.96 on SciFact. Moving from 256 to 1024 increases mean prompt tokens from 308.89 to 1064.75 and from 320.26 to 1086.92 respectively. HotpotQA sentence F1 does not increase with this larger context; SciFact does improve by point estimate. This is descriptive budget sensitivity, not a newly registered interaction test.','','The 2,213 generation-cache entries are below the conservative 2,250 bound because NONE shares answers across budgets and some methods expose exactly identical evidence. Every logical system still has one conceptual LM call and its full prompt/generated-token cost. Cached answer-generation timings below are not independent per-row measurements; no end-to-end/serving-throughput claim is made.','','### Final claim assessment','','| Claim | Validation evidence | Confirmation evidence | Final status |','|---|---|---|---|','| Evidence granularity depends on task/budget | Different VAL rankings and allocation effects | Sentence/passage contrast directions repeat; tight SciFact effect is strongest | Qualitatively supported; interaction magnitude not formally established |','| Sentence selection is a strong simple constrained-budget policy | Frozen fallback selected using VAL | Strong gains over NONE in all four cells; clear SciFact @256 passage advantage | Supported within these cohorts; not universal superiority |','| Large-budget passages can recover | RAW_SKIP competitive/stronger at 1024 | Higher RAW_SKIP point estimates in both datasets; paired intervals include zero | Partially supported / competitive, superiority inconclusive |','| QBGF is universally superior | Universal promotion not established on VAL | HotpotQA @1024 win, mixed other cells | Universal claim not supported; cell-specific QBGF benefit acknowledged |','| Query conditioning matters | D VAL ablation evidence | NO_QUERY deliberately excluded | Validation-supported only |','','No fresh QASPER confirmation exists. These conclusions cover 200 HotpotQA queries/200 groups and 50 SciFact claims/43 groups only. J/K/L is post-hoc explanation on VAL; it did not alter M. LLMLingua/LoRA were not tested. Confirmation is now consumed: do not tune, change methods or reuse it as fresh holdout.','','---','']
 report=p/'week12_M_final_confirmation_report.md';base=report.read_text();marker='## Interpreted closeout'
 # Preserve auto-generated full tables; rerunning this script replaces only this introduction.
 if marker in base:
  title,rest=base.split(marker,1);base=title+rest.split('\n---\n',1)[1]
 first,rest=base.split('\n',1);report.write_text(first+'\n\n'+'\n'.join(intro)+rest)
 print(json.dumps(audit,indent=2))
if __name__=='__main__':main()
